@Component("salesOrder-handler")
@ProcessingGroup("salesOrder-processing-group")
public class SalesOrderEventHandler {
	
	// core constructor
	SalesOrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateSalesOrderEvent
     */
    @EventHandler
    public void handle( CreateSalesOrderEvent event) {
        entityManager.persist(new SalesOrder(event.getSalesOrderId(), event.getOrderNumber(), event.getOrderDate(), event.getTotalAmount(), event.getCustomer(), event.getPlant(), event.getLines(), event.getWorkOrders(), event.getStatus()));
    }

    /*
     * @param	event UpdateSalesOrderEvent
     */
    @EventHandler
    public SalesOrder handle( UpdateSalesOrderEvent event) {
    	entityManager.merge(new SalesOrder(event.getSalesOrderId(), event.getOrderNumber(), event.getOrderDate(), event.getTotalAmount(), event.getCustomer(), event.getPlant(), event.getLines(), event.getWorkOrders(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteSalesOrderEvent
     */
    @EventHandler
    public void on( DeleteSalesOrderEvent event) {
    	SalesOrder entity = new SalesOrder();
   
    	// ------------------------------------------
    	// apply the SalesOrderId
    	// ------------------------------------------
    	entity.setSalesOrderId( event.getSalesOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final SalesOrderRepository salesOrderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(SalesOrderEventHandler.class.getName());

}
